// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated by `opennextjs-cloudflare build`, absent before it
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { rateLimit } from "./src/lib/rate-limit";

/**
 * Custom Worker entry (https://opennext.js.org/cloudflare/howtos/custom-worker) that wraps
 * the OpenNext handler, so clients over their rate limit are turned away before Next.js
 * renders anything.
 */
export default {
  async fetch(request, env, ctx) {
    return (await rateLimit(request, env)) ?? handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
